/**
 * @file main.c
 * @brief owbridge firmware entry point
 *
 * The host interface is selected at compile time with -DHOST_IF=UART|SPI|I2C.
 * The firmware is fully polled: no NVIC interrupts are enabled, and the 1-Wire
 * timing is generated by TIM1+DMA. The main loop is a superloop that polls the
 * selected host interface and the bridge.
 *
 * In the I2C build the loop is priority-scheduled: while an I2C transaction is
 * active the 1-Wire poll is deferred, because its encode/decode can take tens
 * of microseconds and would drop SCL edges at 100 kHz. The 1-Wire timing is
 * hardware-generated, so deferring the poll only delays the state machine. A
 * 50 ms safety valve forces the poll if the I2C bus stalls.
 *
 * -DOWBRIDGE_PROFILE=1 adds a one-off TIM3-based profiler (I2C build only);
 * the results live in RAM and are read over SWD.
 */

#include "board.h"
#include "bridge.h"

#include "onewire.h"

#include "stm32f0xx.h"

#if defined(HOST_IF_UART)
#include "host_uart.h"
#elif defined(HOST_IF_SPI)
#include "host_spi.h"
#elif defined(HOST_IF_I2C)
#include "host_i2c_soft.h"
#if defined(OWBRIDGE_PROFILE)
#include "profile.h"
#endif
#else
#error "Select a host interface: -DHOST_IF=UART, SPI, or I2C"
#endif

int main(void)
{
#if defined(HOST_IF_I2C)
    uint32_t i2c_edge_ms = 0u;
    uint32_t i2c_edges = 0u;
    uint32_t i2c_check_ms = 0u;
    uint8_t i2c_was_busy = 0u;
#endif
#if defined(OWBRIDGE_PROFILE) && defined(HOST_IF_I2C)
    profile_init();
#endif

    board_init();

    /* The archive and the application must agree on the build flags and the
       clock; a mismatch is a dead bus. Fail loudly before the bus is used. */
    if (OW_CONFIG_TOKEN != onewire_config_token()) {
        for (;;) {
        }
    }
    SystemCoreClockUpdate();
    if (!onewire_clock_ok(SystemCoreClock / 1000000u)) {
        for (;;) {
        }
    }

    bridge_init();

#if defined(HOST_IF_UART)
    host_uart_init();
#elif defined(HOST_IF_SPI)
    host_spi_init();
#elif defined(HOST_IF_I2C)
    host_i2c_soft_init();
#endif

    for (;;) {
        /* Keep the millisecond counter advancing even when the bus is idle:
           every other call site sits in a branch that only runs while the
           I2C master is active, which would freeze stats_uptime(). */
        uint32_t now_ms = board_millis();
#if defined(OWBRIDGE_PROFILE) && defined(HOST_IF_I2C)
        if (!prof_cmd_done && now_ms > 1000u) {
            profile_experiment();
        }
        profile_loop_begin();
#endif
        board_watchdog_refresh();
#if defined(HOST_IF_UART)
        host_uart_poll();
        bridge_poll();
#elif defined(HOST_IF_SPI)
        host_spi_poll();
        bridge_poll();
#elif defined(HOST_IF_I2C)
#if defined(OWBRIDGE_PROFILE)
        profile_i2c_begin();
#endif
        host_i2c_soft_poll();
#if defined(OWBRIDGE_PROFILE)
        profile_i2c_end();
#endif
        if (!host_i2c_soft_busy()) {
            i2c_was_busy = 0u;
#if defined(OWBRIDGE_PROFILE)
            profile_bridge_begin();
#endif
            bridge_poll();
#if defined(OWBRIDGE_PROFILE)
            profile_bridge_end();
            profile_start_check(1u, host_i2c_soft_busy());
#endif
        } else {
            /* The valve only needs millisecond resolution. On a fast 100 kHz
               transaction the loop runs several times per millisecond, so
               gate the edge bookkeeping on a new millisecond: the busy path
               must stay short enough to sample every SCL half-period. */
            if (!i2c_was_busy) {
                i2c_was_busy = 1u;
                i2c_edges = host_i2c_soft_edge_count();
                i2c_edge_ms = now_ms;
                i2c_check_ms = now_ms;
            } else if (now_ms != i2c_check_ms) {
                uint32_t edges = host_i2c_soft_edge_count();
                i2c_check_ms = now_ms;
                if (edges != i2c_edges) {
                    i2c_edges = edges;
                    i2c_edge_ms = now_ms;
                } else if ((uint32_t)(now_ms - i2c_edge_ms) > 50u) {
                    /* Safety valve: only a bus with no edges for 50 ms (a
                       wedged master or a held clock) may delay the 1-Wire
                       state machine. A valid long frame keeps producing
                       edges, so it is never interrupted by a long poll. */
                    bridge_poll();
                    i2c_edge_ms = now_ms;
                }
            }
        }
#endif
#if defined(OWBRIDGE_PROFILE) && defined(HOST_IF_I2C)
        profile_loop_end();
#endif
    }
}
